// Builds the design tokens in tokens/ into CSS variables (app/tokens.css) and a
// typed helper (lib/tokens.ts). Usage: node scripts/build-tokens.mjs [--check]
// --check fails instead of writing when the generated files are out of date.
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { cssName, cssValue, loadTokens, rawValue, root, TIERS } from './tokens-lib.mjs';

const HEADER = 'Generated by scripts/build-tokens.mjs from tokens/*.json. Do not edit; change the JSON and run `npm run tokens`.';
const TIER_NOTE = {
  primitive: 'Tier 1 · primitives (--ref-*). Raw palette and scales; only semantic tokens may use them.',
  semantic: 'Tier 2 · semantic. What pages and components use.',
  component: 'Tier 3 · component. Per-component settings built on semantic tokens.',
};

const tokens = loadTokens();
const list = [...tokens.values()];

const css = [`/* ${HEADER} */`, ':root {'];
for (const tier of TIERS) {
  css.push(`  /* ${TIER_NOTE[tier]} */`);
  for (const t of list.filter((x) => x.tier === tier)) css.push(`  ${cssName(t)}: ${cssValue(tokens, t)};`);
}
css.push('}', '');

const publicNames = list.filter((t) => t.tier !== 'primitive').map((t) => cssName(t).slice(2));
const breakpoints = Object.fromEntries(
  list.filter((t) => t.path[0] === 'breakpoint').map((t) => [t.path[1], t.value.value]),
);
const semanticColors = list.filter((t) => t.tier === 'semantic' && t.type === 'color');
const ts = [
  `// ${HEADER}`,
  '',
  '/** Every semantic and component token (CSS variable name without the leading --). */',
  `export type Token =\n${publicNames.map((n) => `  | '${n}'`).join('\n')};`,
  '',
  '/** `var(--name)` for a token, for the few inline styles that need one (e.g. a subject colour). */',
  'export const token = (name: Token) => `var(--${name})`;',
  '',
  '/** Max-width breakpoints in px, matching the @media rules in globals.css. */',
  `export const BREAKPOINTS = ${JSON.stringify(breakpoints)} as const;`,
  '',
  '/**',
  ' * Resolved hex values of the semantic colours, for places that can\'t read CSS',
  ' * variables (the <meta name="theme-color">, the web manifest, third-party widgets).',
  ' * Everywhere else, use the CSS variable.',
  ' */',
  'export const RAW = {',
  ...semanticColors.map((t) => `  '${cssName(t).slice(2)}': '${rawValue(tokens, t)}',`),
  '} as const;',
  '',
].join('\n');

const outputs = [
  [join(root, 'app', 'tokens.css'), css.join('\n')],
  [join(root, 'lib', 'tokens.ts'), ts],
];

if (process.argv.includes('--check')) {
  const stale = outputs.filter(([file, text]) => !existsSync(file) || readFileSync(file, 'utf8') !== text);
  if (stale.length) {
    console.log(`✗ Design tokens are out of date: ${stale.map(([f]) => f.slice(root.length + 1)).join(', ')}. Run npm run tokens.`);
    process.exit(1);
  }
  console.log(`✓ Design tokens up to date (${list.length} tokens)`);
} else {
  for (const [file, text] of outputs) writeFileSync(file, text);
  const count = (tier) => list.filter((t) => t.tier === tier).length;
  console.log(`✓ Built ${list.length} tokens (${count('primitive')} primitive, ${count('semantic')} semantic, ${count('component')} component)`);
}
